82	class MshrTag extends Bundle{  // AddrCalculate向MSHR添加记录并获取Tag的接口
83	  val warp_id = UInt(depth_warp.W)
84	  val wfd = Bool()
85	  val wxd = Bool()
86	  val reg_idxw = UInt((regidx_width + regext_width).W)
87	  val mask = Vec(num_thread, Bool())
88	  val unsigned = Bool()
89	  val isvec = Bool()
90	  val wordOffset1H = Vec(num_thread, UInt(BytesOfWord.W))
91	  val isWrite = Bool()
92	  val spike_info = if (SPIKE_OUTPUT) Some(new InstWriteBack) else None
93	}
94	
95	object ByteExtract{
96	  def apply(isUInt: Bool = true.B, in: UInt = 0.U(xLen.W), sel: UInt = "hf".U(4.W)): UInt = {
97	    val result = Wire(UInt(32.W))
98	    result := MuxCase(
99	      in, Array(
100	        (sel==="hf".U) -> in,
101	        (sel==="hc".U) -> Mux(!in(31)||isUInt, Cat(0.U(16.W),in(31,16)), Cat("hffff".U(16.W),in(31,16))),
102	        (sel==="h3".U) -> Mux(!in(15)||isUInt, Cat(0.U(16.W),in(15,0)), Cat("hffff".U(16.W),in(15,0))),
103	        (sel==="h8".U) -> Mux(!in(31)||isUInt, Cat(0.U(24.W),in(31,24)), Cat("hffffff".U(24.W),in(31,24))),
104	        (sel==="h4".U) -> Mux(!in(23)||isUInt, Cat(0.U(24.W),in(23,16)), Cat("hffffff".U(24.W),in(23,16))),
105	        (sel==="h2".U) -> Mux(!in(15)||isUInt, Cat(0.U(24.W),in(15,8)), Cat("hffffff".U(24.W),in(15,8))),
106	        (sel==="h1".U) -> Mux(!in(7)||isUInt, Cat(0.U(24.W),in(7,0)), Cat("hffffff".U(24.W),in(7,0)))
107	      )
108	    )
109	    result
110	  }
111	}
112	
113	class AddrCalculate(val sharedmemory_maxsize: UInt = 4096.U(32.W)) extends Module{
114	  val io = IO(new Bundle{
115	    val from_fifo = Flipped(DecoupledIO(new vExeData))
116	    val csr_wid = Output(UInt(depth_warp.W))
117	    val csr_pds = Input(UInt(xLen.W))
118	    val csr_numw = Input(UInt(xLen.W))
119	    val csr_tid = Input(UInt(xLen.W))
120	    val to_mshr = DecoupledIO(new Bundle{
121	      val tag = new MshrTag
122	    })
123	    val idx_entry = Input(UInt(log2Up(lsu_nMshrEntry).W))
124	    val flush_dcache = Flipped(DecoupledIO(Bool()))
125	    val to_dcache = DecoupledIO(new DCacheCoreReq_np)
126	    val to_shared = DecoupledIO(new ShareMemCoreReq_np)
127	  })
128	  val s_idle :: s_save :: s_shared :: s_dcache ::s_dcache_1::s_dcache_2:: Nil = Enum(6)
129	  val cnt = new Counter(n = num_thread)
130	  val state = RegInit(init = s_idle)
131	
132	  val reg_save = Reg(new vExeData)
133	  val is_flush = RegInit(false.B)
134	  io.csr_wid:=reg_save.ctrl.wid
135	  //val rdy_fromFIFO = Reg(Bool())
136	  io.from_fifo.ready := state===s_idle && !io.flush_dcache.valid
137	  io.flush_dcache.ready := state === s_idle
138	  val reg_entryID = RegInit(0.U(log2Up(lsu_nMshrEntry).W))
139	
140	  val addr = Wire(Vec(num_thread, UInt(xLen.W)))
141	  val is_shared = Wire(Vec(num_thread, Bool()))
142	  val all_shared = Wire(Bool())
143	
144	
145	  // Address Calculate & Analyze, Comb Logic @reg_save
146	  (0 until num_thread).foreach( x => {
147	    addr(x) :=  Mux(reg_save.ctrl.isvec & reg_save.ctrl.disable_mask,
148	                  Mux(reg_save.ctrl.is_vls12,
149	                    reg_save.in1(x)+reg_save.in2(x),
150	                    (reg_save.in1(x) + reg_save.in2(x))(1,0) + (Cat((io.csr_tid + x.asUInt),0.U(2.W) ) ) + io.csr_pds + (((Cat((reg_save.in1(x)+reg_save.in2(x))(31,2),0.U(2.W)))*io.csr_numw)<<depth_thread) 
151	                  ),
152	                  Mux(reg_save.ctrl.isvec,
153	                    reg_save.in1(x) + Mux(reg_save.ctrl.mop===0.U,
154	                      x.asUInt<<2,
155	                      Mux(reg_save.ctrl.mop===3.U,
156	                        reg_save.in2(x),
157	                        x.asUInt*reg_save.in2(x))
158	                    ),
159	                    reg_save.in1(0) + reg_save.in2(0)
160	                  )
161	                )
162	    is_shared(x) := !reg_save.mask(x) || ( addr(x) >= LDS_BASE.U(32.W) && addr(x) < (LDS_BASE.U(32.W) + sharedmemory_maxsize) )
163	  })
164	  all_shared := Mux(reg_save.ctrl.isvec,
165	    is_shared.asUInt.andR, // "AND" Reduce
166	    is_shared(0)
167	  )
168	  val addr_wire=Wire(UInt(xLen.W))
169	  addr_wire:=addr(PriorityEncoder(reg_save.mask.asUInt))
170	  val tag = Mux(reg_save.mask.asUInt=/=0.U, addr_wire(xLen-1, xLen-1-dcache_TagBits+1), 0.U(dcache_TagBits.W))
171	  val setIdx = Mux(reg_save.mask.asUInt=/=0.U, addr_wire(xLen-1-dcache_TagBits, xLen-1-dcache_TagBits-dcache_SetIdxBits+1), 0.U(dcache_SetIdxBits.W))
172	
173	  val same_tag = Wire(Vec(num_thread, Bool()))
174	    (0 until num_thread).foreach( x =>
175	      same_tag(x) := Mux(reg_save.mask(x), addr(x)(xLen-1, xLen-1-dcache_TagBits-dcache_SetIdxBits+1)===Cat(tag, setIdx), false.B)
176	    )
177	  val blockOffset = Wire(Vec(num_thread, UInt(dcache_BlockOffsetBits.W)))
178	  (0 until num_thread).foreach( x => blockOffset(x) := addr(x)(10, 2) )
179	  val wordOffset1H = Wire(Vec(num_thread, UInt(BytesOfWord.W)))
180	  (0 until num_thread).foreach( x => {
181	  //DONE: Add Control Signals in vExeData.ctrl and define lw lh lb
182	    wordOffset1H(x) := 15.U(4.W)
183	    switch(reg_save.ctrl.mem_whb){
184	      is(MEM_W) { wordOffset1H(x) := 15.U }
185	      is(MEM_H) { wordOffset1H(x) :=
186	        Mux(addr(x)(1)===0.U,
187	          3.U,
188	          12.U
189	        )
190	      }
191	      is(MEM_B) { wordOffset1H(x) := 1.U << addr(x)(1,0) }
192	    }
193	  })
194	  //val reg_toMSHR = Reg(new MshrTag)
195	  //val vld_toMSHR = Reg(Bool())
196	  io.to_mshr.bits.tag.mask := reg_save.mask
197	  io.to_mshr.bits.tag.reg_idxw := reg_save.ctrl.reg_idxw
198	  io.to_mshr.bits.tag.warp_id := reg_save.ctrl.wid
199	  io.to_mshr.bits.tag.wxd:=reg_save.ctrl.wxd
200	  io.to_mshr.bits.tag.wfd:=reg_save.ctrl.wvd
201	  io.to_mshr.bits.tag.isvec := reg_save.ctrl.isvec
202	  io.to_mshr.bits.tag.unsigned := reg_save.ctrl.mem_unsigned
203	  io.to_mshr.bits.tag.wordOffset1H := wordOffset1H
204	  io.to_mshr.valid := state===s_save & (reg_save.ctrl.mem_cmd.orR)
205	  io.to_mshr.bits.tag.isWrite := reg_save.ctrl.mem_cmd(1)
206	  if(SPIKE_OUTPUT){
207	    io.to_mshr.bits.tag.spike_info.get:=reg_save.ctrl.spike_info.get
208	  }
209	  //val reg_toShared = Reg(new toShared)
210	  //val vld_toShared = Reg(Bool())
211	  val data_next=reg_save.in3
212	
213	  io.to_shared.bits.instrId := reg_entryID
214	  // |reg_save| -> |addr & mask| -> |PriorityEncoder| -> |tag & idx| -> |io.to_dcache.bits|
215	  //io.to_shared.bits.tag := tag
216	  io.to_shared.bits.setIdx := setIdx
217	  (0 until num_thread).foreach(x => {
218	    io.to_shared.bits.perLaneAddr(x).blockOffset := blockOffset(x)
219	    io.to_shared.bits.perLaneAddr(x).wordOffset1H := wordOffset1H(x)
220	    io.to_shared.bits.perLaneAddr(x).activeMask := reg_save.mask(x) && (addr(x)(xLen-1, xLen-1-dcache_TagBits+1)===tag && addr(x)(xLen-1-dcache_TagBits, xLen-1-dcache_TagBits-dcache_SetIdxBits+1)===setIdx)
221	  })
222	  io.to_shared.bits.data := data_next//Mux(reg_save.ctrl.mem_cmd(0).asBool, VecInit(Seq.fill(num_thread)(0.U(xLen.W))), reg_save.in3)
223	  io.to_shared.bits.isWrite := reg_save.ctrl.mem_cmd(1)
224	  io.to_shared.valid := state===s_shared
225	
226	  //val vld_toDCache = Reg(Bool())
227	  io.to_dcache.bits.instrId := reg_entryID
228	  if(MMU_ENABLED) {
229	    io.to_dcache.bits.asid.get := reg_save.ctrl.asid.get
230	  }
231	
232	  // |reg_save| -> |addr & mask| -> |PriorityEncoder| -> |tag & idx| -> |io.to_dcache.bits|
233	  io.to_dcache.bits.tag := tag
234	  io.to_dcache.bits.setIdx := setIdx
235	  io.to_dcache.bits.spike_info.foreach{ left =>
236	    left.pc := reg_save.ctrl.pc
237	    left.vaddr := addr_wire
238	  }
239	  val opcode_wire =Wire(UInt(3.W))
240	  val param_wire_alt =Wire(UInt(4.W))
241	  param_wire_alt := Mux(reg_save.ctrl.alu_fn===FN_SWAP,16.U,Mux(reg_save.ctrl.alu_fn===FN_AMOADD,0.U,Mux(reg_save.ctrl.alu_fn===FN_XOR,1.U,
242	    Mux(reg_save.ctrl.alu_fn===FN_AND,3.U,Mux(reg_save.ctrl.alu_fn===FN_OR,2.U,Mux(reg_save.ctrl.alu_fn===FN_MIN,4.U,
243	    Mux(reg_save.ctrl.alu_fn===FN_MAX,5.U,Mux(reg_save.ctrl.alu_fn===FN_MINU,6.U,Mux(reg_save.ctrl.alu_fn===FN_MAXU,7.U,1.U)))))))))
244	  val param_wire=Wire(UInt(4.W))
245	  when(reg_save.ctrl.atomic){
246	    when(reg_save.ctrl.aq &&reg_save.ctrl.rl){
247	      opcode_wire :=Mux(state===s_dcache_2,3.U,Mux(state===s_dcache_1,2.U,3.U))
248	      param_wire :=Mux(state===s_dcache_2,0.U,Mux(state===s_dcache_1,param_wire_alt,0.U))
249	    }.elsewhen(reg_save.ctrl.aq){
250	      opcode_wire :=Mux(state===s_dcache_1,2.U,3.U)
251	      param_wire :=Mux(state===s_dcache_1,param_wire_alt,0.U)
252	    }.elsewhen(reg_save.ctrl.rl){
253	      opcode_wire :=Mux(state===s_dcache_1,3.U,2.U)
254	      param_wire :=Mux(state===s_dcache_1,0.U,param_wire_alt)
255	    }.otherwise{
256	      opcode_wire := Mux(reg_save.ctrl.alu_fn===FN_ADD,reg_save.ctrl.mem_cmd(1),2.U) //todo should consider lr/sc
257	      param_wire :=param_wire_alt
258	    }
259	  }.elsewhen(reg_save.ctrl.fence){
260	    opcode_wire :=3.U
261	    param_wire :=0.U
262	  }.elsewhen(is_flush) { // is_flush: indicate kernel ends! will invalidate L1D instead of flush
263	    opcode_wire := 3.U
264	    param_wire := 0.U
265	  }.otherwise{
266	    opcode_wire :=reg_save.ctrl.mem_cmd(1)
267	    param_wire :=0.U
268	  }
269	  io.to_dcache.bits.opcode :=opcode_wire// fence=invalidate, atomic will split to maximum 3 instructions
270	  io.to_dcache.bits.param :=param_wire
271	
272	  (0 until num_thread).foreach(x => {
273	    io.to_dcache.bits.perLaneAddr(x).blockOffset := blockOffset(x)
274	    io.to_dcache.bits.perLaneAddr(x).wordOffset1H := wordOffset1H(x)
275	    io.to_dcache.bits.perLaneAddr(x).activeMask := Mux(reg_save.ctrl.atomic,reg_save.mask(x)&& (x.asUInt===PriorityEncoder(reg_save.mask.asUInt)),
276	      reg_save.mask(x) && (addr(x)(xLen-1, xLen-1-dcache_TagBits+1)===tag && addr(x)(xLen-1-dcache_TagBits, xLen-1-dcache_TagBits-dcache_SetIdxBits+1)===setIdx)
277	    )
278	
279	  })
280	  io.to_dcache.bits.data := data_next//Mux(reg_save.ctrl.mem_cmd(0).asBool, VecInit(Seq.fill(num_thread)(0.U(xLen.W))), reg_save.in3)
281	 // io.to_dcache.bits.isWrite := reg_save.ctrl.mem_cmd(1)
282	  io.to_dcache.valid := (state===s_dcache) ||(state===s_dcache_1) ||(state===s_dcache_2)
283	  val mask_next = Wire(Vec(num_thread, Bool()))
284	
285	  (0 until num_thread).foreach( x => {                          // update mask
286	    mask_next(x) := Mux(reg_save.ctrl.atomic ,reg_save.mask(x)&& !(x.asUInt===PriorityEncoder(reg_save.mask.asUInt)),reg_save.mask(x) && !(addr(x)(xLen-1, xLen-1-dcache_TagBits+1)===tag && addr(x)(xLen-1-dcache_TagBits, xLen-1-dcache_TagBits-dcache_SetIdxBits+1)===setIdx)
287	    )})
288	  // End of Addr Logic
289	
290	  // FSM State Transfer
291	  switch(state){
292	    is (s_idle){
293	      state := MuxCase(state, Seq(
294	        io.flush_dcache.fire -> s_dcache,
295	        io.from_fifo.fire -> s_save,
296	      ))
297	      cnt.reset()
298	    }
299	    is (s_save){
300	      when(reg_save.ctrl.mem_cmd.orR){ // read or write
301	        when(all_shared && !is_flush){ // shared memory
302	          when(io.to_mshr.fire){state := s_shared}.otherwise{state := s_save}
303	        }.otherwise{ // dcache
304	            when(io.to_mshr.fire) {
305	              state := s_dcache
306	            }.otherwise {
307	              state := s_save
308	            }
309	          }
310	      }.otherwise{ state := s_idle }
311	    }
312	    is (s_shared){
313	      when(io.to_shared.fire){
314	        when(cnt.value>=num_thread.U || mask_next.asUInt===0.U){
315	          cnt.reset(); state := s_idle
316	        }.otherwise{
317	          cnt.inc(); state := s_shared
318	        }
319	      }.otherwise{state := s_shared}
320	    }
321	    is (s_dcache) {
322	      when(is_flush) {
323	        when(io.to_dcache.fire) {
324	          state := s_idle
325	        }.otherwise {
326	          state := state
327	        }
328	      }.otherwise {
329	        when(io.to_dcache.fire) {
330	          when((reg_save.ctrl.atomic && reg_save.ctrl.aq) || (reg_save.ctrl.atomic && reg_save.ctrl.rl)) {
331	            state := s_dcache_1
332	          }.elsewhen(cnt.value >= num_thread.U || mask_next.asUInt === 0.U) {
333	            cnt.reset();
334	            state := s_idle
335	          }.otherwise {
336	            cnt.inc();
337	            state := s_dcache
338	          }
339	        }.otherwise {
340	          state := s_dcache
341	        }
342	      }
343	    }
344	    is(s_dcache_1){
345	      when(io.to_dcache.fire){
346	
347	          when(reg_save.ctrl.aq && reg_save.ctrl.rl) {
348	            state := s_dcache_2
349	          }.elsewhen(cnt.value>=num_thread.U || mask_next.asUInt===0.U){
350	            cnt.reset(); state := s_idle
351	        }.otherwise{
352	            cnt.inc(); state :=s_dcache
353	        }
354	      }.otherwise{
355	        state :=s_dcache_1
356	      }
357	    }
358	    is(s_dcache_2){
359	      when(io.to_dcache.fire){
360	        when(cnt.value>=num_thread.U ||mask_next.asUInt===0.U){
361	          cnt.reset();state:=s_idle
362	        }.otherwise{
363	          cnt.inc(); state := s_dcache
364	        }
365	      }.otherwise{state := s_dcache_2}
366	    }
367	  }
368	  // FSM Operation
369	  switch(state){
370	    is (s_idle){
371	      when(io.flush_dcache.fire){
372	        reg_save := RegInit(0.U.asTypeOf(new vExeData))
373	        reg_save.ctrl.mem_cmd := 1.U
374	      }.elsewhen(io.from_fifo.fire){ // Next: s_save
375	        reg_save := io.from_fifo.bits   // save data
376	        when(io.from_fifo.bits.ctrl.atomic){
377	          reg_save.ctrl.aq := true.B
378	        }.otherwise{
379	          reg_save.ctrl.aq:=io.from_fifo.bits.ctrl.aq
380	        }
381	        reg_save.mask := Mux(io.from_fifo.bits.ctrl.isvec, io.from_fifo.bits.mask, VecInit((1.U(num_thread.W)).asBools))
382	      }.otherwise{reg_save := RegInit(0.U.asTypeOf(new vExeData))}
383	    }
384	    is (s_save){
385	      when(reg_save.ctrl.mem_cmd.orR){//===1.U){  // read
386	        when(io.to_mshr.fire){reg_entryID := io.idx_entry}  // get entryID from MSHR
387	      }
388	    }
389	    is (s_shared){
390	      // Maybe Nothing here :-)
391	      when(io.to_shared.fire){                                      // request is sent
392	        reg_save.mask := mask_next
393	      }.otherwise{
394	        reg_save.mask := reg_save.mask
395	      }
396	    }
397	    is (s_dcache){
398	      when(io.to_dcache.fire){                                      // request is sent
399	        reg_save.mask := mask_next
400	      }.otherwise{
401	        reg_save.mask := reg_save.mask
402	      }
403	    }
404	  }
405	
406	  switch(state){
407	    is (s_idle){
408	      when(io.flush_dcache.fire){
409	        is_flush := true.B
410	      }.otherwise{
411	        is_flush := false.B
412	      }
413	    }
414	    is(s_dcache){
415	      when(io.to_dcache.fire){
416	        is_flush := false.B
417	      }.otherwise{
418	        is_flush := is_flush
419	      }
420	    }
421	  }
422	
423	  if (SPIKE_OUTPUT) {
424	  when(state === s_save && io.to_mshr.fire && reg_save.ctrl.mem) {
425	    val common_prefix = p"sm ${reg_save.ctrl.spike_info.get.sm_id} warp ${Decimal(reg_save.ctrl.wid)} 0x${Hexadecimal(reg_save.ctrl.spike_info.get.pc)} 0x${Hexadecimal(reg_save.ctrl.spike_info.get.inst)} "
426	    when(!reg_save.ctrl.isvec) {
427	      when(reg_save.ctrl.mem_cmd === IDecode.M_XRD) {
428	        printf(common_prefix + p"lsu.r x ${reg_save.ctrl.reg_idxw} op ${reg_save.ctrl.mop} @ ${Hexadecimal(reg_save.in1(0))}+${Hexadecimal(reg_save.in2(0))}\n")
429	      } .elsewhen(reg_save.ctrl.mem_cmd === IDecode.M_XWR) {
