530	class LSUexe() extends Module{
531	// default size: 128 * (num_thread=8) * (xlen/8=4) = 4KByte
532	  val io = IO(new Bundle{
533	    val lsu_req = Flipped(DecoupledIO(new vExeData()))
534	    val dcache_rsp = Flipped(DecoupledIO(new DCacheCoreRsp_np()))
535	    //val lsu_rsp = DecoupledIO(new WriteBackControl())
536	    val lsu_rsp = DecoupledIO(new MSHROutput)
537	    val dcache_req = DecoupledIO(new DCacheCoreReq_np())
538	    val shared_req = DecoupledIO(new ShareMemCoreReq_np())
539	    val shared_rsp = Flipped(DecoupledIO(new DCacheCoreRsp_np))
540	    val fence_end = Output(UInt(num_warp.W))
541	    val flush_dcache = Flipped(DecoupledIO(Bool()))
542	
543	    val csr_wid = Output(UInt(depth_warp.W))
544	    val csr_pds = Input(UInt(xLen.W))
545	    val csr_numw = Input(UInt(xLen.W))
546	    val csr_tid = Input(UInt(xLen.W))
547	  })
548	  val sharedmemory_addr_max = sharemem_size.U(32.W)
549	  //val sharedmemory = Module(new SharedMemoryV2(nSharedMemoryEntry, num_thread, xLen, lsu_nMshrEntry)) // default: 128
550	
551	  val InputFIFO = Module(new Queue(new vExeData, entries=1, pipe=true))
552	  InputFIFO.io.enq <> io.lsu_req
553	
554	  val AddrCalc = Module(new AddrCalculate(sharedmemory_addr_max))
555	  AddrCalc.io.from_fifo <> InputFIFO.io.deq
556	  io.dcache_req <> AddrCalc.io.to_dcache
557	  io.shared_req <> AddrCalc.io.to_shared
558	  AddrCalc.io.flush_dcache <> io.flush_dcache
559	
560	  val rspArbiter = Module(new Arbiter(new DCacheCoreRsp_np, n = 2))
561	  rspArbiter.io.in(1) <> io.shared_rsp
562	  rspArbiter.io.in(0) <> io.dcache_rsp
563	
564	  // SOME MSHR INTERFACE
565	  val Coalscer = Module(new MSHRv2)
566	  //val outputFIFO = Module(new Queue(new MSHROutput, num_warp+1, pipe=true))
567	  Coalscer.io.from_dcache <> rspArbiter.io.out
568	  Coalscer.io.from_addr <> AddrCalc.io.to_mshr
569	  AddrCalc.io.idx_entry:=Coalscer.io.idx_entry
570	  io.lsu_rsp <> Coalscer.io.to_pipe
571	
572	  val shiftBoard=VecInit(Seq.fill(num_warp)(Module(new ShiftBoard(lsu_num_entry_each_warp)).io))
573	  shiftBoard.zipWithIndex.foreach{case(a,b)=> {
574	    a.left:=io.lsu_req.fire & io.lsu_req.bits.ctrl.wid===b.asUInt
575	    a.right:=io.lsu_rsp.fire & io.lsu_rsp.bits.tag.warp_id===b.asUInt
576	    }}
577	  io.fence_end:=VecInit(shiftBoard.map(x=>x.empty)).asUInt
578	  io.lsu_req.ready:=Mux(shiftBoard(io.lsu_req.bits.ctrl.wid).full,false.B,InputFIFO.io.enq.ready)
579	  InputFIFO.io.enq.valid:=Mux(shiftBoard(io.lsu_req.bits.ctrl.wid).full,false.B,io.lsu_req.valid)
580	
581	  io.csr_wid:=AddrCalc.io.csr_wid
582	  AddrCalc.io.csr_tid:=io.csr_tid
583	  AddrCalc.io.csr_pds:=io.csr_pds
584	  AddrCalc.io.csr_numw:=io.csr_numw
585	}
