587	class ShiftBoard(val depth:Int) extends Module{
588	  val io=IO(new Bundle{
589	    val left=Input(Bool())
590	    val right=Input(Bool())
591	    val full=Output(Bool())
592	    val empty=Output(Bool())
593	  })
594	  val taps=(Seq.fill(depth)(RegInit(false.B)))
595	  val left_move=io.left
596	  val right_move=io.right
597	
598	  taps.zipWithIndex.foreach {case(a,b)=>
599	    if(b==0) a:= Mux(left_move^right_move,Mux(left_move,true.B,taps(b+1)),a)
600	    else if(b==depth-1) a:= Mux(left_move^right_move,Mux(left_move,taps(b-1),false.B),a)
601	    else a:=Mux(left_move^right_move,Mux(left_move,taps(b-1),taps(b+1)),a)
602	  }
603	  io.full:= taps(depth-1)//Mux(left_move^right_move,Mux(left_move,taps(depth-2),false.B),taps(depth-1))
604	  io.empty:= !Mux(left_move^right_move,Mux(left_move,true.B,taps(1)),taps(0))
605	}

